package com.mathengine.data;import android.content.Context;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;
public final class CalculatorDataRepository{private final Context app;public CalculatorDataRepository(Context c){app=c.getApplicationContext();}public String readText(String n)throws Exception{if(n==null||n.contains("..")||n.contains("/"))throw new IllegalArgumentException("Invalid dataset name");try(InputStream in=app.getAssets().open("default_data/"+n);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int k;while((k=in.read(b))!=-1)o.write(b,0,k);return o.toString(StandardCharsets.UTF_8.name());}}public JSONObject readObject(String n)throws Exception{return new JSONObject(readText(n));}public JSONArray readArray(String n)throws Exception{return new JSONArray(readText(n));}}
